import Database from 'better-sqlite3'
import { drizzle, type BetterSQLite3Database } from 'drizzle-orm/better-sqlite3'
import * as schema from './schema'

/** SQL migrations generated by drizzle-kit, embedded at build time. */
const migrationFiles = import.meta.glob('../../../../drizzle/*.sql', {
  query: '?raw',
  import: 'default',
  eager: true,
}) as Record<string, string>

export type OrbitDb = BetterSQLite3Database<typeof schema>

export interface DatabaseHandle {
  db: OrbitDb
  sqlite: Database.Database
  close(): void
}

export function listMigrations(): { name: string; sql: string }[] {
  return Object.entries(migrationFiles)
    .map(([path, sql]) => ({ name: path.split('/').pop()!.replace(/\.sql$/, ''), sql }))
    .sort((a, b) => a.name.localeCompare(b.name))
}

/** Applies pending migrations inside a transaction each. Idempotent. */
export function runMigrations(sqlite: Database.Database): string[] {
  sqlite.exec(
    `CREATE TABLE IF NOT EXISTS __orbit_migrations (name TEXT PRIMARY KEY, applied_at TEXT NOT NULL)`,
  )
  const applied = new Set(
    (sqlite.prepare('SELECT name FROM __orbit_migrations').all() as { name: string }[]).map((r) => r.name),
  )
  const ran: string[] = []
  for (const m of listMigrations()) {
    if (applied.has(m.name)) continue
    const statements = m.sql
      .split('--> statement-breakpoint')
      .map((s) => s.trim())
      .filter(Boolean)
    sqlite.transaction(() => {
      for (const statement of statements) sqlite.exec(statement)
      sqlite
        .prepare('INSERT INTO __orbit_migrations (name, applied_at) VALUES (?, ?)')
        .run(m.name, new Date().toISOString())
    })()
    ran.push(m.name)
  }
  return ran
}

export function openDatabase(file: string): DatabaseHandle {
  const sqlite = new Database(file)
  sqlite.pragma('journal_mode = WAL')
  sqlite.pragma('foreign_keys = ON')
  sqlite.pragma('busy_timeout = 3000')
  runMigrations(sqlite)
  const db = drizzle(sqlite, { schema })
  return { db, sqlite, close: () => sqlite.close() }
}
